# Linker version script — export only the public C API.
# Applied by bridge/lito.toml via -Wl,--version-script=...
#
# Why a version script instead of C_VISIBILITY_PRESET=hidden + annotations:
# ipc_v3.{h,c} is auto-generated by wayproto-gen, so hand-annotating its
# prototypes with an export macro would be lost on regeneration. The
# generated codec uses ww_* for messages and waywallen_*_free for named
# value lifecycles.
WAYWALLEN_BRIDGE_0 {
    global:
        ww_*;
        waywallen_*_free;
    local:
        *;
};
